package com.flippingfriend.companion;
import com.flippingfriend.core.*;import java.nio.file.*;import java.sql.*;import org.junit.Test;import static org.junit.Assert.*;
public class BuyReplacementIntentPersistenceTest{
 static BuyReplacementIntent intent(){return BuyReplacementIntent.cancelAuthorized("intent-1","offer-1","plan-1",2,4151,"Abyssal whip",1000,500,100,100,200);}
 @Test public void replayAdvanceAndRestartAreDurable()throws Exception{Path db=Files.createTempDirectory("intent").resolve("db");BuyReplacementIntent i=intent();try(SqliteStore s=new SqliteStore(db)){s.saveBuyReplacementIntent(i);s.saveBuyReplacementIntent(i);BuyReplacementIntent a=BuyReplacementIntentTransition.apply(i,BuyReplacementIntentState.CANCEL_OBSERVED,110,"offer-1","plan-1",true,false,false);s.saveBuyReplacementIntent(a);assertEquals(1,s.buyReplacementIntents().size());}try(SqliteStore s=new SqliteStore(db)){BuyReplacementIntent a=s.buyReplacementIntents().get(0);assertEquals(BuyReplacementIntentState.CANCEL_OBSERVED,a.getState());assertEquals(400,a.getRemainderQuantity());assertEquals("offer-1",a.getOriginalOfferIdentity());assertEquals("plan-1",a.getRecommendationId());}}
 @Test public void mismatchPreservesPriorRow()throws Exception{Path db=Files.createTempDirectory("mismatch").resolve("db");try(SqliteStore s=new SqliteStore(db)){s.saveBuyReplacementIntent(intent());BuyReplacementIntent bad=BuyReplacementIntent.cancelAuthorized("intent-1","other","plan-1",2,4151,"Abyssal whip",1000,500,100,100,200);try{s.saveBuyReplacementIntent(bad);fail();}catch(IllegalArgumentException expected){}assertEquals("offer-1",s.buyReplacementIntents().get(0).getOriginalOfferIdentity());}}
 @Test public void malformedRowFailsClosed()throws Exception{Path db=Files.createTempDirectory("bad").resolve("db");try(SqliteStore s=new SqliteStore(db)){s.saveBuyReplacementIntent(intent());}try(Connection c=DriverManager.getConnection("jdbc:sqlite:"+db.toAbsolutePath());Statement s=c.createStatement()){s.execute("UPDATE buy_replacement_intent_projection SET remainder_quantity=399");}try(SqliteStore s=new SqliteStore(db)){try{s.buyReplacementIntents();fail();}catch(IllegalArgumentException expected){}}}
 @Test public void legacyDatabaseGainsTable()throws Exception{Path db=Files.createTempDirectory("legacy").resolve("db");Files.createDirectories(db.getParent());try(Connection c=DriverManager.getConnection("jdbc:sqlite:"+db.toAbsolutePath());Statement s=c.createStatement()){s.execute("CREATE TABLE event_log (id INTEGER PRIMARY KEY, observed_at INTEGER NOT NULL, correlation_id TEXT NOT NULL, event_type TEXT NOT NULL, payload TEXT NOT NULL)");}try(SqliteStore s=new SqliteStore(db)){s.saveBuyReplacementIntent(intent());assertEquals(1,s.buyReplacementIntents().size());}}
}